import{c as t,Q as a,j as o,m as n}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"What is FinSight?","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/what-is-finsight.md","filePath":"getting-started/what-is-finsight.md","lastUpdated":null}'),i={name:"getting-started/what-is-finsight.md"};function s(r,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="what-is-finsight" tabindex="-1">What is FinSight? <a class="header-anchor" href="#what-is-finsight" aria-label="Permalink to &quot;What is FinSight?&quot;">​</a></h1><p>FinSight is not a hosted SaaS, a stock picker, or a marketing dashboard. It is a calm, local-first ledger with an AI copilot that helps you make the next good financial decision.</p><h2 id="the-core-idea" tabindex="-1">The core idea <a class="header-anchor" href="#the-core-idea" aria-label="Permalink to &quot;The core idea&quot;">​</a></h2><ol><li><strong>You own the ledger.</strong> Accounts, transactions, budgets, categories, goals — all live in an encrypted per-user SQLite database on your server. The browser is a viewer, not the vault.</li><li><strong>AI is opt-in and replaceable.</strong> Categorization and Copilot use the provider you configure, or none at all. Local Ollama keeps inference on your machine; remote providers receive only the redacted context needed for a task.</li><li><strong>Principles guide behaviour.</strong> Six ideas from <em>Babylon, Ramsey, Sethi, Housel, Hill, Kiyosaki</em> are encoded in the wellness context and system prompt — not as motivational copy, but as calculations (savings rate, emergency-fund months, snowball order, allocation).</li></ol><h2 id="screens-you-will-use" tabindex="-1">Screens you will use <a class="header-anchor" href="#screens-you-will-use" aria-label="Permalink to &quot;Screens you will use&quot;">​</a></h2><ul><li><strong>Today</strong> — net worth, income/expenses, savings rate, category stream, and one clear next action.</li><li><strong>Copilot</strong> — conversational planning with streaming, typed finance cards, and reviewable action bundles.</li><li><strong>Insights</strong> — anomalies, patterns, memory, and a needs-review feed.</li><li><strong>Accounts</strong> — manual and SimpleFIN-synced accounts, balance history, net worth.</li><li><strong>Transactions</strong> — search, filters, review queues, transfers, splits, drawer editing.</li><li><strong>Budget</strong> — envelope planning, To Budget, carryover, and Conscious Spending allocation.</li><li><strong>Categories</strong> — groups, guidance, and spending types (Need/Want/Saving/Investment).</li><li><strong>Recurring</strong>, <strong>Goals</strong>, <strong>Reports</strong>, <strong>Scenarios</strong>, <strong>Journey</strong>, <strong>Recipes</strong>, <strong>Rules</strong>, <strong>Settings</strong>.</li></ul><h2 id="philosophy-in-practice" tabindex="-1">Philosophy in practice <a class="header-anchor" href="#philosophy-in-practice" aria-label="Permalink to &quot;Philosophy in practice&quot;">​</a></h2><blockquote><p>“A quiet way to understand, plan, and master your money.”</p></blockquote><p>That means fewer totals, more decisions. Surfaces are flat and calm; lime (<code>#C9F950</code>) is reserved for state and action. The app marks financial figures with <code>money</code> so privacy mode can blur them.</p><h2 id="who-it-is-for" tabindex="-1">Who it is for <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who it is for&quot;">​</a></h2><ul><li>People who want a self-hosted alternative to cloud budget apps.</li><li>Households that share a server but keep separate encrypted databases.</li><li>Anyone who wants AI help without handing the ledger to a vendor.</li></ul><p>If you want confetti, streaks, and piles of coins, this is the wrong product. FinSight is an instrument — check it, make one good decision, close it.</p><p>Next: <a href="/FinSight/getting-started/installation">Installation</a>.</p>',13)])])}const u=t(i,[["render",s]]);export{p as __pageData,u as default};
